package dominoes

// Domino is a single stone: a pair of dot counts, one for each half.
type Domino [2]int

// MakeChain computes a way to order the given dominoes so that they form a
// correct domino chain: the dots on one half of a stone match the dots on the
// neighboring half of an adjacent stone, and the dots on the two halves that
// don't have a neighbor (the first and last stone) match each other.
// It reports whether such a chain exists.
func MakeChain(input []Domino) ([]Domino, bool) {
	switch len(input) {
	case 0:
		return []Domino{}, true
	case 1:
		d := input[0]
		if d[0] == d[1] {
			return []Domino{d}, true
		}
		return []Domino{}, false
	}

	// A closed chain requires every value to appear an even number of times.
	// This quick check rejects many impossible inputs before searching.
	degree := make(map[int]int, 2*len(input))
	for _, d := range input {
		degree[d[0]]++
		degree[d[1]]++
	}
	for _, v := range degree {
		if v%2 != 0 {
			return []Domino{}, false
		}
	}

	n := len(input)
	used := make([]bool, n)
	chain := make([]Domino, 0, n)
	var result []Domino

	// search extends the current chain (whose last half shows `next`) with
	// unused dominoes, trying both orientations of each.
	var search func(next int)
	search = func(next int) {
		if result != nil {
			return
		}
		if len(chain) == n {
			if chain[0][0] == chain[n-1][1] {
				result = make([]Domino, n)
				copy(result, chain)
			}
			return
		}
		for i := range input {
			if used[i] {
				continue
			}
			d := input[i]
			for _, dd := range [2]Domino{{d[0], d[1]}, {d[1], d[0]}} {
				if dd[0] != next {
					continue
				}
				used[i] = true
				chain = append(chain, dd)
				search(dd[1])
				chain = chain[:len(chain)-1]
				used[i] = false
				if result != nil {
					return
				}
			}
		}
	}

	for i := range input {
		d := input[i]
		for _, dd := range [2]Domino{{d[0], d[1]}, {d[1], d[0]}} {
			used[i] = true
			chain = append(chain, dd)
			search(dd[1])
			chain = chain[:len(chain)-1]
			used[i] = false
			if result != nil {
				return result, true
			}
		}
	}
	return []Domino{}, false
}

